<?php

declare(strict_types=1);

namespace App\Models;

use App\Models\Concerns\HasTranslatableName;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * Mirror locale della `Category1` dell'hub (Interior/Outdoor, roadmap #24).
 * I campi sincronizzati (`name`, `slug`, `hub_updated_at`) sono scritti solo
 * dal motore di sync (`App\Sync\Category1Syncer`), mai dall'utente.
 *
 * `hero_image_desktop`/`hero_image_mobile` sono invece contenuti editoriali
 * locali (card CATEGORIA della board CMS, `.docs/analisi-board-cms.md`): il
 * syncer non li tocca, li gestisce solo `Category1Resource` nell'admin.
 *
 * Soft-delete: vedi `App\Models\Product` per il motivo.
 */
class Category1 extends Model
{
    use HasTranslatableName;
    use SoftDeletes;

    protected $table = 'categories_1';

    protected $fillable = [
        'global_id',
        'name',
        'slug',
        'hub_updated_at',
        'hero_image_desktop',
        'hero_image_mobile',
    ];

    protected function casts(): array
    {
        return [
            'name' => 'array',
            'hub_updated_at' => 'datetime',
        ];
    }
}

