<?php

declare(strict_types=1);

namespace App\Sync;

use App\Models\Category1;
use AtrioTeam\HubSync\AbstractSyncer;

/**
 * Pull incrementale delle `Category1` (Interior/Outdoor) dall'hub (roadmap
 * hub #24).
 */
class Category1Syncer extends AbstractSyncer
{
    protected function resource(): string
    {
        return 'categories-1';
    }

    protected function modelClass(): string
    {
        return Category1::class;
    }

    /**
     * @param array<string, mixed> $item
     */
    protected function upsert(array $item): bool
    {
        $exists = Category1::where('global_id', $item['global_id'])->exists();

        Category1::updateOrCreate(
            ['global_id' => $item['global_id']],
            [
                'name' => $item['name'],
                'slug' => $item['slug'],
                'hub_updated_at' => $item['updated_at'] ?? null,
            ],
        );

        return ! $exists;
    }
}
