use Illuminate\Database\Migrations\Migration;
use Illuminate\Database\Schema\Blueprint;
use Illuminate\Support\Facades\Schema;

/**
 * Conteggio delle cancellazioni recepite dal sync (hub roadmap #24:
 * `deleted_at` nel payload), simmetrico a created/updated/failed — è
 * l'informazione che l'operatore deve vedere nello storico "Import dati"
 * (design doc Parte 2) per sapere che dei record sono stati rimossi, non
 * solo creati o aggiornati.
 */
return new class () extends Migration {
    public function up(): void
    {
        Schema::table('sync_runs', function (Blueprint $table) {
            $table->unsignedInteger('deleted_count')->default(0)->after('failed_count');
        });
    }

    public function down(): void
    {
        Schema::table('sync_runs', function (Blueprint $table) {
            $table->dropColumn('deleted_count');
        });
    }
};
