<?php

declare(strict_types=1);

namespace AtrioTeam\HubSync\Models;

use AtrioTeam\HubSync\SyncStatus;
use Illuminate\Database\Eloquent\Model;

/**
 * Storico dei sync (design doc Parte 2 di atmosphera-admin): entità di
 * dominio, non log tecnico.
 */
class SyncRun extends Model
{
    protected $fillable = [
        'resource',
        'status',
        'started_at',
        'finished_at',
        'created_count',
        'updated_count',
        'deleted_count',
        'failed_count',
        'error',
        'item_errors',
    ];

    protected function casts(): array
    {
        return [
            'status' => SyncStatus::class,
            'started_at' => 'datetime',
            'finished_at' => 'datetime',
            'item_errors' => 'array',
        ];
    }

    public function isInProgress(): bool
    {
        /** @var SyncStatus $status */
        $status = $this->status;

        return in_array($status, [SyncStatus::Pending, SyncStatus::Running], true);
    }
}

