7	use App\Filament\Pages\Sync\SyncResourceDetail;
8	use AtrioTeam\HubSync\Models\SyncRun;
9	use AtrioTeam\HubSync\SyncRegistry;
10	use AtrioTeam\HubSync\SyncStatus;
11	use Filament\Support\ArrayRecord;
12	use Filament\Tables\Columns\TextColumn;
13	use Filament\Tables\Table;
14	use Filament\Widgets\TableWidget;
15	use Illuminate\Contracts\Support\Htmlable;
16	use Illuminate\Support\Collection;
17	
18	/**
19	 * Card d'ingresso della sincronizzazione con l'hub, in forma tabellare: una
20	 * riga per ogni risorsa registrata in SyncRegistry, con l'esito dell'ultimo
21	 * sync e il link al dettaglio (storico + trigger manuale).
22	 */
23	class SyncOverviewWidget extends TableWidget
24	{
25	    protected int | string | array $columnSpan = 'full';
26	
27	    protected function getTableHeading(): string | Htmlable | null
28	    {
29	        return 'Sincronizzazione hub';
30	    }
31	
32	    public function table(Table $table): Table
33	    {
34	        return $table
35	            ->heading(null)
36	            ->records(fn (): Collection => $this->rows())
37	            ->columns([
38	                TextColumn::make('label')
39	                    ->label('Risorsa'),
40	                TextColumn::make('lastRunAt')
41	                    ->label('Ultimo sync')
42	                    ->placeholder('Mai eseguito'),
43	                TextColumn::make('status')
44	                    ->label('Esito')
45	                    ->badge()
46	                    ->color(fn (?SyncStatus $state): string => $state?->color() ?? 'gray')
47	                    ->formatStateUsing(fn (?SyncStatus $state): string => $state?->label() ?? 'Mai eseguito'),
48	            ])
49	            ->recordUrl(function (array $record): string {
50	                /** @var string $url */
51	                $url = $record['url'];
52	
53	                return $url;
54	            })
55	            ->paginated(false);
56	    }
57	
58	    /**
59	     * @return Collection<int, non-empty-array<string, SyncStatus|string|null>>
60	     */
61	    private function rows(): Collection
62	    {
63	        return collect(SyncRegistry::all())
64	            ->map(function (array $definition, string $slug): array {
65	                $lastRun = SyncRun::query()
66	                    ->where('resource', $slug)
67	                    ->latest('started_at')
68	                    ->first();
69	
70	                /** @var \Illuminate\Support\Carbon|null $startedAt */
71	                $startedAt = $lastRun?->started_at;
72	
73	                /** @var SyncStatus|null $status */
74	                $status = $lastRun?->status;
75	
76	                return [
77	                    ArrayRecord::getKeyName() => $slug,
78	                    'label' => $definition['label'],
79	                    'lastRunAt' => $startedAt?->diffForHumans(),
80	                    'status' => $status,
81	                    'url' => SyncResourceDetail::getUrl(['resource' => $slug]),
82	                ];
83	            })
84	            ->values();
85	    }
86	}
