5	namespace AtrioTeam\HubSync;
6	
7	use InvalidArgumentException;
8	
9	/**
10	 * Risorse sincronizzabili dall'hub, dichiarate in
11	 * config('hub-sync.resources') dall'app consumer. Aggiungere una nuova
12	 * entità è dichiarativo: non serve toccare motore o UI.
13	 */
14	class SyncRegistry
15	{
16	    public static function has(string $slug): bool
17	    {
18	        return array_key_exists($slug, self::allResources());
19	    }
20	
21	    public static function label(string $slug): string
22	    {
23	        return self::definition($slug)['label'];
24	    }
25	
26	    public static function syncerFor(string $slug): Syncer
27	    {
28	        $class = self::definition($slug)['syncer'];
29	
30	        /** @var Syncer $syncer */
31	        $syncer = app($class);
32	
33	        return $syncer;
34	    }
35	
36	    /**
37	     * @return array<string, array{label: string, syncer: class-string<Syncer>}>
38	     */
39	    public static function all(): array
40	    {
41	        return self::allResources();
42	    }
43	
44	    /**
45	     * @return array{label: string, syncer: class-string<Syncer>}
46	     */
47	    private static function definition(string $slug): array
48	    {
49	        $definition = self::allResources()[$slug] ?? null;
50	
51	        if ($definition === null) {
52	            throw new InvalidArgumentException("Risorsa di sync [{$slug}] non registrata.");
53	        }
54	
55	        return $definition;
56	    }
57	
58	    /**
59	     * @return array<string, array{label: string, syncer: class-string<Syncer>}>
60	     */
61	    private static function allResources(): array
62	    {
63	        /** @var array<string, array{label: string, syncer: class-string<Syncer>}> $resources */
64	        $resources = config('hub-sync.resources', []);
65	
66	        return $resources;
67	    }
68	}
