10	use AtrioTeam\HubSync\SyncStatus;
11	use Filament\Actions\Action;
12	use Filament\Notifications\Notification;
13	use Filament\Pages\Page;
14	use Filament\Schemas\Components\EmbeddedTable;
15	use Filament\Schemas\Schema;
16	use Filament\Tables;
17	use Filament\Tables\Table;
18	use Illuminate\Contracts\Support\Htmlable;
19	use Illuminate\Support\HtmlString;
20	use Symfony\Component\HttpKernel\Exception\NotFoundHttpException;
21	
22	/**
23	 * Storico sync per una singola risorsa registrata in SyncRegistry, con action
24	 * di trigger manuale (design doc Parte 2: "Import dati" è UI di dominio, non
25	 * log tecnico).
26	 */
27	class SyncResourceDetail extends Page implements Tables\Contracts\HasTable
28	{
29	    use Tables\Concerns\InteractsWithTable;
30	
31	    protected static ?string $slug = 'sync/{resource}';
32	
33	    protected static bool $shouldRegisterNavigation = false;
34	
35	    public string $resource;
36	
37	    public function mount(string $resource): void
38	    {
39	        if (! SyncRegistry::has($resource)) {
40	            throw new NotFoundHttpException("Risorsa di sync [{$resource}] non registrata.");
41	        }
42	
43	        $this->resource = $resource;
44	    }
45	
46	    public function getTitle(): string | Htmlable
47	    {
48	        // FilamentShield risolve il titolo di ogni pagina scoperta per
49	        // generare i permessi (`shield:generate --all`) istanziando la
50	        // classe senza passare da mount(): $this->resource non è ancora
51	        // valorizzato in quel caso.
52	        if (! isset($this->resource)) {
53	            return 'Sincronizzazione';
54	        }
55	
56	        return 'Sincronizzazione - ' . SyncRegistry::label($this->resource);
57	    }
58	
59	    public function content(Schema $schema): Schema
60	    {
61	        return $schema->components([
62	            EmbeddedTable::make(),
63	        ]);
64	    }
65	
66	    public function table(Table $table): Table
67	    {
68	        return $table
69	            ->query(fn () => SyncRun::query()->where('resource', $this->resource))
70	            ->defaultSort('started_at', 'desc')
71	            ->poll('5s')
72	            ->columns([
73	                Tables\Columns\TextColumn::make('started_at')
74	                    ->label('Avviato')
75	                    ->dateTime(timezone: 'Europe/Rome')
76	                    ->placeholder('—')
77	                    ->sortable(),
78	                Tables\Columns\TextColumn::make('finished_at')
79	                    ->label('Terminato')
80	                    ->dateTime(timezone: 'Europe/Rome')
81	                    ->placeholder('—'),
82	                Tables\Columns\TextColumn::make('status')
83	                    ->label('Esito')
84	                    ->badge()
85	                    ->formatStateUsing(fn (SyncStatus $state): string => $state->label())
86	                    ->color(fn (SyncStatus $state): string => $state->color()),
87	                Tables\Columns\TextColumn::make('created_count')->label('Creati'),
88	                Tables\Columns\TextColumn::make('updated_count')->label('Aggiornati'),
89	                Tables\Columns\TextColumn::make('deleted_count')->label('Cancellati'),
90	                Tables\Columns\TextColumn::make('failed_count')
91	                    ->label('Falliti')
92	                    ->color(fn (int $state): ?string => $state > 0 ? 'danger' : null),
93	            ])
94	            ->recordActions([
95	                Action::make('errors')
96	                    ->label('Errori')
97	                    ->icon('heroicon-o-exclamation-triangle')
98	                    ->color('danger')
99	                    ->visible(fn (SyncRun $record): bool => filled($record->error) || filled($record->item_errors))
100	                    ->modalHeading('Errori del sync')
101	                    ->modalContent(fn (SyncRun $record) => $this->errorsModalContent($record))
102	                    ->modalSubmitAction(false)
103	                    ->modalCancelActionLabel('Chiudi'),
104	            ])
105	            ->emptyStateHeading('Nessun sync eseguito finora');
106	    }
107	
108	    protected function getHeaderActions(): array
109	    {
110	        return [
111	            Action::make('import')
112	                ->label('Importa dati ora')
113	                ->icon('heroicon-o-arrow-path')
114	                ->disabled(fn (): bool => SyncRun::query()
115	                    ->where('resource', $this->resource)
116	                    ->whereIn('status', [SyncStatus::Pending, SyncStatus::Running])
117	                    ->exists())
118	                ->action(function (): void {
119	                    $run = SyncRun::create([
120	                        'resource' => $this->resource,
121	                        'status' => SyncStatus::Pending,
122	                    ]);
123	
124	                    RunSyncJob::dispatch($run->id);
125	
126	                    Notification::make()
127	                        ->title('Sync avviato')
128	                        ->success()
129	                        ->send();
130	                }),
131	        ];
132	    }
133	
134	    private function errorsModalContent(SyncRun $record): Htmlable
135	    {
136	        $lines = [];
137	
138	        if (filled($record->error)) {
139	            $lines[] = e($record->error);
140	        }
141	
142	        /** @var array<int, array{global_id?: string, message?: string}> $itemErrors */
143	        $itemErrors = $record->item_errors ?? [];
144	
145	        foreach ($itemErrors as $itemError) {
146	            $lines[] = e(($itemError['global_id'] ?? '?') . ': ' . ($itemError['message'] ?? ''));
147	        }
148	
149	        return new HtmlString('<span class="text-sm">' . implode("\n", $lines) . '</span>');
150	    }
151	}
