44	                    ->label('Esito')
45	                    ->badge()
46	                    ->color(fn (?SyncStatus $state): string => $state?->color() ?? 'gray')
47	                    ->formatStateUsing(fn (?SyncStatus $state): string => $state?->label() ?? 'Mai eseguito'),
48	                TextColumn::make('trashedCount')
49	                    ->label('Cancellati da rivedere')
50	                    ->badge()
51	                    ->color(fn (int $state): string => $state > 0 ? 'warning' : 'gray')
52	                    ->formatStateUsing(fn (int $state): string => (string) $state),
53	            ])
54	            ->recordUrl(function (array $record): string {
55	                /** @var string $url */
56	                $url = $record['url'];
57	
58	                return $url;
59	            })
60	            ->paginated(false);
61	    }
62	
63	    /**
64	     * @return Collection<int, non-empty-array<string, SyncStatus|string|null>>
65	     */
66	    private function rows(): Collection
67	    {
68	        return collect(SyncRegistry::all())
69	            ->map(function (array $definition, string $slug): array {
70	                $lastRun = SyncRun::query()
71	                    ->where('resource', $slug)
72	                    ->latest('started_at')
73	                    ->first();
74	
75	                /** @var \Illuminate\Support\Carbon|null $startedAt */
76	                $startedAt = $lastRun?->started_at;
77	
78	                /** @var SyncStatus|null $status */
79	                $status = $lastRun?->status;
80	
81	                return [
82	                    ArrayRecord::getKeyName() => $slug,
83	                    'label' => $definition['label'],
84	                    'lastRunAt' => $startedAt?->diffForHumans(),
85	                    'status' => $status,
86	                    'trashedCount' => SyncRegistry::syncerFor($slug)->trashedCount(),
87	                    'url' => SyncResourceDetail::getUrl(['resource' => $slug]),
88	                ];
89	            })
90	            ->values();
91	    }
92	}
