1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\HubSync;
6	
7	use AtrioTeam\HubSync\Models\SyncRun;
8	use Illuminate\Database\Eloquent\Model;
9	use Illuminate\Support\Carbon;
10	use Throwable;
11	
12	/**
13	 * Meccanica comune a ogni Syncer: paginazione, conteggi, cattura degli
14	 * errori per singolo record (senza bloccare il run) e watermark
15	 * incrementale sull'ultimo run riuscito per la stessa risorsa. Le
16	 * sottoclassi sanno solo come si chiama la risorsa sull'hub, il model del
17	 * mirror locale e come si fa l'upsert di un singolo item.
18	 */
19	abstract class AbstractSyncer implements Syncer
20	{
21	    public function __construct(protected readonly HubClient $client = new HubClient())
22	    {
23	    }
24	
25	    abstract protected function resource(): string;
26	
27	    /**
28	     * Model Eloquent del mirror locale, soft-delete: usato da `delete()` per
29	     * risolvere il record da cancellare senza che ogni sottoclasse ripeta la
30	     * stessa query `where('global_id', ...)`.
31	     *
32	     * @return class-string<Model>
33	     */
34	    abstract protected function modelClass(): string;
35	
36	    /**
37	     * @param array<string, mixed> $item
38	     * @return bool true se il record locale non esisteva ancora (creato)
39	     */
40	    abstract protected function upsert(array $item): bool;
41	
42	    public function sync(SyncRun $run): void
43	    {
44	        $watermark = $this->watermark();
45	        $itemErrors = [];
46	
47	        foreach ($this->client->paginate($this->resource(), $watermark) as $page) {
48	            foreach ($page as $item) {
49	                try {
50	                    // L'hub include le righe soft-deleted nel payload invece
51	                    // di filtrarle (hub roadmap #24): è così che il mirror
52	                    // locale scopre una cancellazione, non con un endpoint o
53	                    // un parametro a parte.
54	                    if (($item['deleted_at'] ?? null) !== null) {
55	                        if ($this->delete($item)) {
56	                            $run->increment('deleted_count');
57	                        }
58	
59	                        continue;
60	                    }
61	
62	                    $created = $this->upsert($item);
63	
64	                    $run->increment($created ? 'created_count' : 'updated_count');
65	                } catch (Throwable $e) {
66	                    $run->increment('failed_count');
67	                    $itemErrors[] = [
68	                        'global_id' => $item['global_id'] ?? null,
69	                        'message' => $e->getMessage(),
70	                    ];
71	                }
72	            }
73	        }
74	
75	        if ($itemErrors !== []) {
76	            $run->update(['item_errors' => $itemErrors]);
77	        }
78	    }
79	
80	    public function trashedCount(): int
81	    {
82	        $modelClass = $this->modelClass();
83	
84	        if (! method_exists($modelClass, 'onlyTrashed')) {
85	            return 0;
86	        }
87	
88	        /** @var \Illuminate\Database\Eloquent\Builder<Model> $query */
89	        $query = $modelClass::onlyTrashed();
90	
91	        return $query->count();
92	    }
93	
94	    /**
95	     * Upsert consapevole del soft-delete, per le sottoclassi il cui mirror è
96	     * `SoftDeletes`: se il record esiste già ma è trashed (ripristinato lato
97	     * hub dopo essere stato cancellato), lo ripristina invece di provare a
98	     * crearne uno nuovo — `updateOrCreate()` di Eloquent, filtrato dal global
99	     * scope di SoftDeletes, non troverebbe la riga trashed e fallirebbe
100	     * sull'unique di `global_id` tentando un insert duplicato.
101	     *
102	     * @param array<string, mixed> $keyAttributes
103	     * @param array<string, mixed> $values
104	     * @return bool true se il mirror locale non esisteva ancora (creato)
105	     */
106	    protected function upsertMirror(array $keyAttributes, array $values): bool
107	    {
108	        $modelClass = $this->modelClass();
109	
110	        $query = method_exists($modelClass, 'withTrashed')
111	            ? $modelClass::withTrashed()
112	            : $modelClass::query();
113	
114	        /** @var Model|null $record */
115	        $record = $query->where($keyAttributes)->first();
116	        $wasNew = $record === null;
117	
118	        if ($record === null) {
119	            $record = new $modelClass();
120	        } elseif (method_exists($record, 'trashed') && $record->trashed()) {
121	            $record->restore();
122	        }
123	
124	        $record->forceFill([...$keyAttributes, ...$values])->save();
125	
126	        return $wasNew;
127	    }
128	
129	    /**
130	     * Soft-cancella il mirror locale corrispondente all'item. `false` se non
131	     * c'è nulla da fare (record mai importato, o già cancellato in un sync
132	     * precedente) — non è un errore, solo un caso senza effetto da contare.
133	     *
134	     * @param array<string, mixed> $item
135	     */
136	    private function delete(array $item): bool
137	    {
138	        $modelClass = $this->modelClass();
139	
140	        $record = $modelClass::where('global_id', $item['global_id'])->first();
141	
142	        // trashed()/delete() vengono dal trait SoftDeletes: qui verificato a
143	        // runtime invece che nel tipo, perché un trait non entra in una
144	        // intersection type e il model arriva come class-string generico.
145	        if ($record === null || ! method_exists($record, 'trashed') || $record->trashed()) {
146	            return false;
147	        }
148	
149	        $record->delete();
150	
151	        return true;
152	    }
153	
154	    private function watermark(): ?Carbon
155	    {
156	        $lastSuccess = SyncRun::query()
157	            ->where('resource', $this->resource())
158	            ->where('status', SyncStatus::Success)
159	            ->latest('started_at')
160	            ->first();
161	
162	        if ($lastSuccess === null) {
